import React, { useState } from "react";

function CoffeeTable() {
  const [activeText, setActiveText] = useState("");
  const [clickedCroissants, setClickedCroissants] = useState([]);

  const croissantTexts = {
    croissant1:
      "בקשה להיתר חו״ל לאנשי קבע ולחיילי החובה תוגש בדיגיטל (באפליקציית אתר צה״ל).",
    croissant2:
      "יש להזין בקשה ל'היתר יציאה לחו״ל' באתר צה״ל.",
    croissant3:
      "יודגש, כי באתר צה״ל יוגשו בקשות ע״ח חופשה שנתית בלבד.",
    croissant4:
      "חו״ל בתפקיד יוגש באופן ידני למשרד המשא״ן.",
  };

  const handleCroissantClick = (croissantId) => {
    setActiveText(croissantTexts[croissantId]);

    setClickedCroissants((prev) =>
      prev.includes(croissantId) ? prev : [...prev, croissantId]
    );
  };

  const isClicked = (croissantId) => clickedCroissants.includes(croissantId);

  return (
    <div className="coffee-table-wrapper">
      <svg
        className="coffee-table-svg"
        viewBox="0 0 888 802"
        fill="none"
        xmlns="http://www.w3.org/2000/svg"
        xmlnsXlink="http://www.w3.org/1999/xlink"
      >
<rect width="888" height="802" fill="url(#pattern0_209_49)"/>
<rect
  className={isClicked("croissant1") ? "empty-plate-clickable" : ""}
  x="435"
  y="530.205"
  width="183.81"
  height="116.76"
  transform="rotate(-26.5661 435 530.205)"
  fill="url(#pattern1_209_49)"
  onClick={() => isClicked("croissant1") && setActiveText(croissantTexts.croissant1)}
/>
{!isClicked("croissant1") && (
        <rect
          className="croissant-clickable"
          x="479.007"
          y="495.546"
          width="128.636"
          height="91.3989"
          fill="url(#pattern2_209_49)"
          onClick={() => handleCroissantClick("croissant1")}
        />
      )}
<rect
  className={isClicked("croissant2") ? "empty-plate-clickable" : ""}
  x="254.223"
  y="404"
  width="183.81"
  height="116.76"
  transform="rotate(57.2714 254.223 404)"
  fill="url(#pattern3_209_49)"
  onClick={() => isClicked("croissant2") && setActiveText(croissantTexts.croissant2)}
/>
{!isClicked("croissant2") && (
        <rect
          className="croissant-clickable"
          x="217.397"
          y="582.203"
          width="128.636"
          height="91.3989"
          transform="rotate(-97.3857 217.397 582.203)"
          fill="url(#pattern4_209_49)"
          onClick={() => handleCroissantClick("croissant2")}
        />
      )}
<rect
  className={isClicked("croissant3") ? "empty-plate-clickable" : ""}
  x="518.543"
  y="169"
  width="183.81"
  height="116.76"
  transform="rotate(33.5578 518.543 169)"
  fill="url(#pattern5_209_49)"
  onClick={() => isClicked("croissant3") && setActiveText(croissantTexts.croissant3)}
/>
{!isClicked("croissant3") && (
        <rect
          className="croissant-clickable"
          x="570.153"
          y="191.217"
          width="128.636"
          height="91.3989"
          transform="rotate(60.5144 570.153 191.217)"
          fill="url(#pattern6_209_49)"
          onClick={() => handleCroissantClick("croissant3")}
        />
      )}
{clickedCroissants.length > 0 && (
        <>
          <rect x="261" y="303" width="320" height="203" fill="url(#pattern7_209_49)" />
          <rect x="286" y="330" width="275" height="134" fill="#D9D9D9" fillOpacity="0.22" />

          {activeText && (
            <foreignObject x="305" y="345" width="240" height="105">
              <div className="plate-text" xmlns="http://www.w3.org/1999/xhtml">
                {activeText}
              </div>
            </foreignObject>
          )}
        </>
      )}
<rect
  className={isClicked("croissant4") ? "empty-plate-clickable" : ""}
  x="175"
  y="250.485"
  width="183.81"
  height="116.76"
  transform="rotate(-26.6638 175 250.485)"
  fill="url(#pattern8_209_49)"
  onClick={() => isClicked("croissant4") && setActiveText(croissantTexts.croissant4)}
/>
{!isClicked("croissant4") && (
        <rect
          className="croissant-clickable"
          x="220"
          y="216"
          width="128.636"
          height="91.3989"
          fill="url(#pattern9_209_49)"
          onClick={() => handleCroissantClick("croissant4")}
        />
      )}
<defs>
<pattern id="pattern0_209_49" patternContentUnits="objectBoundingBox" width="1" height="1">
<use xlinkHref="#image0_209_49" transform="matrix(0.00100798 0 0 0.00111607 -0.116347 0)"/>
</pattern>
<pattern id="pattern1_209_49" patternContentUnits="objectBoundingBox" width="1" height="1">
<use xlinkHref="#image1_209_49" transform="matrix(0.00108799 0 0 0.00171278 -0.14536 -0.252475)"/>
</pattern>
<pattern id="pattern2_209_49" patternContentUnits="objectBoundingBox" width="1" height="1">
<use xlinkHref="#image2_209_49" transform="matrix(0.00099859 0 0 0.00140542 -0.113105 -0.138889)"/>
</pattern>
<pattern id="pattern3_209_49" patternContentUnits="objectBoundingBox" width="1" height="1">
<use xlinkHref="#image1_209_49" transform="matrix(0.00108799 0 0 0.00171278 -0.14536 -0.252475)"/>
</pattern>
<pattern id="pattern4_209_49" patternContentUnits="objectBoundingBox" width="1" height="1">
<use xlinkHref="#image2_209_49" transform="matrix(0.00099859 0 0 0.00140542 -0.113105 -0.138889)"/>
</pattern>
<pattern id="pattern5_209_49" patternContentUnits="objectBoundingBox" width="1" height="1">
<use xlinkHref="#image1_209_49" transform="matrix(0.00108799 0 0 0.00171278 -0.14536 -0.252475)"/>
</pattern>
<pattern id="pattern6_209_49" patternContentUnits="objectBoundingBox" width="1" height="1">
<use xlinkHref="#image2_209_49" transform="matrix(0.00099859 0 0 0.00140542 -0.113105 -0.138889)"/>
</pattern>
<pattern id="pattern7_209_49" patternContentUnits="objectBoundingBox" width="1" height="1">
<use xlinkHref="#image1_209_49" transform="matrix(0.00108119 0 0 0.00170435 -0.131951 -0.251232)"/>
</pattern>
<pattern id="pattern8_209_49" patternContentUnits="objectBoundingBox" width="1" height="1">
<use xlinkHref="#image1_209_49" transform="matrix(0.00108799 0 0 0.00171278 -0.14536 -0.252475)"/>
</pattern>
<pattern id="pattern9_209_49" patternContentUnits="objectBoundingBox" width="1" height="1">
<use xlinkHref="#image2_209_49" transform="matrix(0.00099859 0 0 0.00140542 -0.113105 -0.138889)"/>
</pattern>
<image id="image0_209_49" width="1195" height="896" preserveAspectRatio="none" xlinkHref="data:image/png;base64,"/>
<image id="image1_209_49" width="1195" height="896" preserveAspectRatio="none" xlinkHref="data:image/png;base64,"/>
<image id="image2_209_49" width="1195" height="896" preserveAspectRatio="none" xlinkHref="data:image/png;base64,"/>
</defs>
</svg>

    </div>
  );
}

export default CoffeeTable;
